/**
 * generate-content-seed.js
 *
 * Generates supabase-migration-v15-seed.sql by transforming the static
 * TypeScript data files (library-data, cinema-data, resources-data) into
 * SQL INSERT statements for the `resources` table.
 *
 * Run:  node scripts/generate-content-seed.js
 * Output: supabase-migration-v15-seed.sql  (printed to stdout, redirected by the npm script)
 */

const fs = require('fs');
const path = require('path');

// ── Helpers ────────────────────────────────────────────────────────────────────

const sq = (s) => (s == null ? 'NULL' : `'${String(s).replace(/'/g, "''")}'`);
const arr = (a) => (a == null || a.length === 0 ? 'NULL' : `ARRAY[${a.map(sq).join(',')}]`);
const bool = (b) => (b == null ? 'NULL' : b ? 'true' : 'false');
const num = (n) => (n == null ? 'NULL' : String(n));

function slugify(str) {
  return str
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 80);
}

