// ── SQL generation ─────────────────────────────────────────────────────────────

function libraryRow(item) {
  return `(${sq(item.title)}, ${sq(item.description)}, 'approved', 'public', ${arr(item.tags)}, ${sq(item.category)}, 'library', ${sq(item.slug)}, ${sq(item.author || null)}, NULL, NULL, ${num(item.year)}, ${sq(item.url || null)}, ${sq(item.type)}, ${bool(item.isFree)}, ${sq(item.howToAccess || null)}, ${bool(item.isEssential || false)}, ${arr(item.format || null)}, NULL, false, false, NULL, NULL, NULL)`;
}

function cinemaRow(item) {
  return `(${sq(item.title)}, ${sq(item.description)}, 'approved', 'public', ${arr(item.tags)}, ${sq(item.category)}, 'cinema', ${sq(item.slug)}, ${sq(item.author || null)}, ${sq(item.director || null)}, ${sq(item.creator || null)}, ${num(item.year)}, ${sq(item.url || null)}, ${sq(item.type)}, ${bool(item.isFree)}, ${sq(item.howToAccess || null)}, ${bool(item.isEssential || false)}, NULL, ${arr(item.platform || null)}, ${bool(item.hasAD || false)}, ${bool(item.hasCaptions || false)}, ${num(item.runtimeMinutes || null)}, NULL, NULL)`;
}

function resourceRow(item) {
  const slug = slugify(item.name).slice(0, 80);
  return `(${sq(item.name)}, ${sq(item.description)}, 'approved', 'public', ${arr(item.tags || [])}, ${sq(item.category)}, 'accessibility', ${sq(item.url)}, NULL, NULL, NULL, NULL, ${sq(item.url)}, ${sq(item.type)}, true, NULL, false, NULL, NULL, false, false, NULL, ${sq(item.location || null)}, NULL)`;
}

const COLS = `(title, description, status, visibility, tags, category, section, slug, author, director, creator, year, url, item_type, is_free, how_to_access, is_essential, format_list, platform_list, has_ad, has_captions, duration_minutes, location_note, admin_notes)`;

const lines = [];
lines.push(`-- supabase-migration-v15-seed.sql`);
lines.push(`-- Seeds all Library, Cinema, and Accessibility Resource items into the resources table.`);
lines.push(`-- Run this in Supabase SQL Editor AFTER running migrations v1-v14.`);
lines.push(`-- Safe to re-run: uses ON CONFLICT DO NOTHING (skips items that already exist).`);
lines.push(``);

lines.push(`-- ── Library items (${LIBRARY_ITEMS.length}) ────────────────────────────────────────────────────────`);
lines.push(`INSERT INTO resources ${COLS} VALUES`);
lines.push(LIBRARY_ITEMS.map(libraryRow).join(',\n'));
lines.push(`ON CONFLICT (section, slug) WHERE slug IS NOT NULL DO NOTHING;`);
lines.push(``);

lines.push(`-- ── Cinema items (${CINEMA_ITEMS.length}) ────────────────────────────────────────────────────────`);
lines.push(`INSERT INTO resources ${COLS} VALUES`);
lines.push(CINEMA_ITEMS.map(cinemaRow).join(',\n'));
lines.push(`ON CONFLICT (section, slug) WHERE slug IS NOT NULL DO NOTHING;`);
lines.push(``);

lines.push(`-- ── Accessibility resource items (${RESOURCE_ITEMS.length}) ─────────────────────────────────────────────`);
lines.push(`-- For accessibility resources, slug = url (matches resource_favorites table)`);
lines.push(`INSERT INTO resources ${COLS} VALUES`);
lines.push(RESOURCE_ITEMS.map(resourceRow).join(',\n'));
lines.push(`ON CONFLICT (section, slug) WHERE slug IS NOT NULL DO NOTHING;`);
lines.push(``);
lines.push(`-- Done. Total: ${LIBRARY_ITEMS.length + CINEMA_ITEMS.length + RESOURCE_ITEMS.length} items seeded.`);

const output = lines.join('\n');
const outPath = path.join(__dirname, '..', 'supabase-migration-v15-seed.sql');
fs.writeFileSync(outPath, output, 'utf8');
console.error(`✓ Written to supabase-migration-v15-seed.sql (${LIBRARY_ITEMS.length} library + ${CINEMA_ITEMS.length} cinema + ${RESOURCE_ITEMS.length} accessibility = ${LIBRARY_ITEMS.length + CINEMA_ITEMS.length + RESOURCE_ITEMS.length} items)`);
